const CODE_SRC = "{\n  // Liquid Mercury: mercury beads bridge and merge, the colon drips into a pool, and the changing digits melt behind a chrome slab.\n  const MS = 100, TAU = 6.283185307179586;\n  const C = /*PER*/[];\n  /*V*/\n  const sl = {}; const g = (h) => sl[h] || (sl[h] = slot(h));\n  const ease = (t) => { t = Math.max(0, Math.min(1, t)); return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; };\n  const SH = [0, 3.5, 7, 10.5, 14];\n  const melt = (key, tens, units, ts) => {\n    const P = C[key], pt = g(key + 't'), l = g(key + 'l'), r = g(key + 'r'), bl = g(key + 'p');\n    if (ts < -1.7 || ts >= 2.0) { pt.hide(); l.hide(); r.hide(); bl.hide(); return; }\n    pt(P.x, P.y, V[key + 't'].p);\n    if (ts < -0.9 || ts >= 1.2) {\n      const i = ts < -0.9 ? Math.min(4, Math.floor((ts + 1.7) / 0.16)) : 4 - Math.min(4, Math.floor((ts - 1.2) / 0.16));\n      l(Math.round(P.x + SH[i]), P.y, V[key + 'l'][i === 4 ? 'ball' : 'd' + tens + 'k' + i]); r(Math.round(P.x + 68 - SH[i]), P.y, V[key + 'r'][i === 4 ? 'ball' : 'd' + units + 'k' + i]); bl.hide();\n    } else {\n      l.hide(); r.hide();\n      const pic = ts < -0.5 ? 'pr' + Math.min(4, Math.floor((ts + 0.9) / 0.08)) : ts < 0.8 ? 'w' + (Math.floor((ts + 0.5) / 0.3) % 3) : 'pr' + (4 - Math.min(4, Math.floor((ts - 0.8) / 0.08)));\n      bl(P.x + 68 - 48, P.y + 68 - 32, V[key + 'p'][pic]);\n    }\n  };\n  const tick = () => {\n    const now = Date.now(), d = new Date(now), t = now / 1000, sec = d.getSeconds() + d.getMilliseconds() / 1000, min = d.getMinutes();\n    // bead pairs: apart, a bridge, one bigger bead\n    for (const p of C.pairs) {\n      const th = TAU * t / p.Tm + p.ph, u = Math.cos(th), s = 2 * p.Ax * Math.abs(u), dy = p.ay * Math.sin(2 * th);\n      const a = g('b' + p.id + 'a'), b = g('b' + p.id + 'b'), va = V['b' + p.id + 'a'], vb = V['b' + p.id + 'b'];\n      const ax = p.cx + p.Ax * u, ay = p.cy + dy, bx = p.cx - p.Ax * u, by = p.cy - dy;\n      if (s >= 36) { a(Math.round(ax - 28), Math.round(ay - 16), va.bead); b(Math.round(bx - 16), Math.round(by - 16), vb.bead); }\n      else {\n        const k = s >= 26 ? 'br1' : s >= 14 ? 'br2' : 'mg', pic = k === 'mg' ? va.mg : va[u < 0 ? k : k + 'm'];\n        a(Math.round(p.cx - 28), Math.round(p.cy + (ay - p.cy + (by - p.cy)) / 2 - 16), pic); b.hide();\n      }\n    }\n    // the colon drips: grow, fall, splash, ripple (every 5 s)\n    const pc = (now % 5000) / 5000, dr = g('drop'), cr = g('crown'), rp = g('ripple');\n    if (pc < 0.12) dr(C.cx - 10, C.by - 6, V.drop.h0);\n    else if (pc < 0.24) dr(C.cx - 10, C.by - 6, V.drop.h1);\n    else if (pc < 0.34) dr(C.cx - 10, C.by - 6, V.drop.h2);\n    else if (pc < 0.58) { const f = (pc - 0.34) / 0.24, yc = C.by + 16 + (C.pool - 8 - C.by - 16) * f * f; dr(C.cx - 10, Math.round(yc - 19), V.drop.fall); }\n    else dr.hide();\n    if (pc >= 0.58 && pc < 0.7) cr(C.cx - 28, C.pool - 34, V.crown[['c0', 'c1', 'c2'][Math.min(2, Math.floor((pc - 0.58) / 0.04))]]); else cr.hide();\n    if (pc >= 0.58 && pc < 0.93) rp(C.cx - 70, C.pool - 16, V.ripple['r' + Math.min(3, Math.floor((pc - 0.58) / 0.0875))]); else rp.hide();\n    // the melt: the two digits that change shrink into balls, unite into one blob, hold through the change, split, and grow into the new digits\n    const ts = sec >= 58.3 ? sec - 60 : sec;\n    melt('m', Math.floor(min / 10), min % 10, ts);\n    const hr = d.getHours(), hourChanges = (min === 59 && ts < 0) || (min === 0 && ts >= 0);   // 24-hour digits\n    melt('h', Math.floor(hr / 10), hr % 10, hourChanges ? ts : 99);\n  };\n  /*RUNTIME*/\n}\n";
const RUNTIME_SRC = "  // ---- shared runtime: slot setter that skips unchanged calls, and a loop that runs only while the face is on screen ----\n  const SL = {};\n  const slot = (h) => {\n    if (SL[h]) return SL[h];\n    const w = W[h], f = F[h]; let key = '';\n    const s = (x, y, i, ww, hh) => {\n      const k = x + '|' + y + '|' + i + '|' + ww + '|' + hh;\n      if (k === key) return;\n      key = k;\n      const p = { x: pxv(x), y: pxv(y) };\n      if (i !== undefined) p.src = f[i];\n      if (ww !== undefined) { p.w = pxv(ww); p.h = pxv(hh); }\n      w.setProperty(ui.prop.MORE, p);\n    };\n    s.hide = () => { if (key === 'hide') return; key = 'hide'; w.setProperty(ui.prop.MORE, { src: f[V[h].__blank] }); };\n    return (SL[h] = s);\n  };\n  let gen = 0, running = false;\n  const safe = () => { try { tick(); } catch (e) { /* a bad frame must not stop the loop */ } };\n  const loop = (g) => {\n    if (!running || g !== gen) return;\n    safe();\n    if (running && g === gen) { try { setTimeout(() => loop(g), MS); } catch (e) {} }\n  };\n  const start = () => {\n    gen++; running = true; const g = gen;\n    try { setTimeout(() => loop(g), MS); } catch (e) {}\n    safe();\n  };\n  const stop = () => { running = false; gen++; };\n  ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });\n  start();\n";
const W = dev().w, H = dev().h, CX = W / 2, TAU = Math.PI * 2, rad = (d) => d * Math.PI / 180;
const mk = (w, h) => { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; };
const E = (n) => project.elements.find((e) => e.name === n);
let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
