const addBar = async (name, dataType, x, y, len, lw, color, o = {}) => {
  const e = await addElement('BAR', { dataType }); e.name = name; Object.assign(e, { dataType, x, y, length: len, lineWidth: lw, color, rounded: true, show: 'normal' }, o); return e;
