    const lv = (i + 1) / 10, col = lv <= 0.2 ? cols[2] : lv <= 0.5 ? cols[1] : cols[0];
    names.push(addProjectImage('bat/' + key + '_' + i + '.png', (mkcell || cell)(w, h, lv, col, frame), {}).name);
  }
